body:
Underline and strikethrough transparency seems to have been hardcoded in https://github.com/godotengine/godot/pull/84233

If I make this change...

```cpp
diff --git a/scene/gui/rich_text_label.cpp b/scene/gui/rich_text_label.cpp
index 2448db6b7f..b0ab45c1a9 100644
--- a/scene/gui/rich_text_label.cpp
+++ b/scene/gui/rich_text_label.cpp
@@ -1122,13 +1122,11 @@ int RichTextLabel::_draw_line(ItemFrame *p_frame, int p_line, const Vector2 &p_o
                                                        ul_start = p_ofs + Vector2(off_step.x, off_step.y);
                                                        ul_color_prev = font_color;
                                                        ul_color = font_color;
-                                                       ul_color.a *= 0.5;
                                                } else if (!ul_started) {
                                                        ul_started = true;
                                                        ul_start = p_ofs + Vector2(off_step.x, off_step.y);
                                                        ul_color_prev = font_color;
                                                        ul_color = font_color;
-                                                       ul_color.a *= 0.5;
                                                }
                                        } else if (ul_started) {
                                                ul_started = false;
@@ -1144,13 +1142,11 @@ int RichTextLabel::_draw_line(ItemFrame *p_frame, int p_line, const Vector2 &p_o
                                                        dot_ul_start = p_ofs + Vector2(off_step.x, off_step.y);
                                                        dot_ul_color_prev = font_color;
                                                        dot_ul_color = font_color;
-                                                       dot_ul_color.a *= 0.5;
                                                } else if (!dot_ul_started) {
                                                        dot_ul_started = true;
                                                        dot_ul_start = p_ofs + Vector2(off_step.x, off_step.y);
                                                        dot_ul_color_prev = font_color;
                                                        dot_ul_color = font_color;
-                                                       dot_ul_color.a *= 0.5;
                                                }
                                        } else if (dot_ul_started) {
                                                dot_ul_started = false;
@@ -1166,13 +1162,11 @@ int RichTextLabel::_draw_line(ItemFrame *p_frame, int p_line, const Vector2 &p_o
                                                        st_start = p_ofs + Vector2(off_step.x, off_step.y);
                                                        st_color_prev = font_color;
                                                        st_color = font_color;
-                                                       st_color.a *= 0.5;
                                                } else if (!st_started) {
                                                        st_started = true;
                                                        st_start = p_ofs + Vector2(off_step.x, off_step.y);
                                                        st_color_prev = font_color;
                                                        st_color = font_color;
-                                                       st_color.a *= 0.5;
                                                }
                                        } else if (st_started) {
                                                st_started = false;
```

... then it looks fine...

![Image](https://github.com/user-attachments/assets/acbb0cef-4018-4ea2-984b-a48556b56271)

... but I don't know if that simplistic change would make non-pixel fonts look bad. Perhaps it needs to be solved with new theme options.

@bruvzg Hi! Do you remember the reason for hardcoding the alpha for underline and strikethrough as 0.5 in RichTextLabel?
